1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.util.MembershipLevel;
8	
9	/**
10	 * Caps a newly created owner's {@code membershipLevel} so it cannot exceed one above the current
11	 * maximum {@code membershipLevel} among the owner's existing household members (those sharing the
12	 * same {@code householdId}). The cap is stamped as {@code membershipLevelCap} and honoured by
13	 * {@link MembershipLevel#of(Owner)} whenever the owner is mapped, so it survives the round-trip to
14	 * the database and applies to later reads too.
15	 *
16	 * <p>Only undeclared joiners are capped. A declared household member ({@code sharesHousehold: true})
17	 * is left uncapped - it earns its level from its own points - whereas an owner that merely shares an
18	 * existing household is held to one above the household's current top level. When the owner joins no
19	 * existing household member the cap is left unset, so no cap applies.
20	 *
21	 * <p>Runs after {@link AssignHousehold} (the household id is finalized) and before the owner is saved.
22	 */
23	public class AssignMembershipCap {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return; // declared household member - not capped
28	        }
29	        String householdId = owner.getHouseholdId();
30	        if (householdId == null) {
31	            return;
32	        }
33	        Integer maxLevel = null;
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (Boolean.TRUE.equals(existing.getDeleted())) {
36	                continue;
37	            }
38	            if (!householdId.equals(existing.getHouseholdId())) {
39	                continue;
40	            }
41	            int level = MembershipLevel.of(existing);
42	            if (maxLevel == null || level > maxLevel) {
43	                maxLevel = level;
44	            }
45	        }
46	        if (maxLevel != null) {
47	            owner.setMembershipLevelCap(maxLevel + 1);
48	        }
49	    }
50	}
